import{_ as t,C as n,o as i,c as s,E as o,a2 as r}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse('{"title":"Weekly 003 — Ownership Is the Control Plane of Agentic Work","description":"","frontmatter":{"title":"Weekly 003 — Ownership Is the Control Plane of Agentic Work","date":"2026-08-02","column":"digital-employee","category":"weekly","summary":"Cross-analysis of three evidence-validated Daily Research Notes concludes that reliable agentic systems must explicitly assign work, control, state, authority, evidence, and completion ownership at every execution boundary.","sources":["Digital Employee Daily 003 — Computer Use Requires an Observable Action–State Loop","Industry Architecture Daily 003 — A2A and MCP Define Different Interoperability Boundaries","Open-source Engineering Daily 003 — Manager Orchestration and Handoffs Encode Different Ownership Models"],"outline":"deep","cover":"/assets/covers/weekly-003-cover-v2.jpg"},"headers":[],"relativePath":"en/research/weekly/weekly-003.md","filePath":"en/research/weekly/weekly-003.md","lastUpdated":1787407830000}'),l={name:"en/research/weekly/weekly-003.md"};function c(d,e,p,h,u,m){const a=n("ArticleCover");return i(),s("div",null,[o(a,{image:"/assets/covers/weekly-003-cover-v2.jpg",kicker:"Weekly Research · 003",title:"Ownership Is the Control Plane of Agentic Work",summary:"Reliable Agent systems do not merely route actions. They make ownership, authority, evidence, and completion explicit at every boundary.",version:"W003",status:"Published 2026-08-02",languageHref:"/zh/research/weekly/weekly-003",languageLabel:"简体中文"}),e[0]||(e[0]=r(`<h2 id="evidence-scope" tabindex="-1">Evidence scope <a class="header-anchor" href="#evidence-scope" aria-label="Permalink to &quot;Evidence scope&quot;">​</a></h2><p>This synthesis uses only evidence-validated Daily Research Notes published during the seven-day window <strong>2026-07-27 through 2026-08-02</strong>.</p><p>Exactly three Daily notes met the eligibility rule. All three were produced and verified by Research OS Engine Production Test V1, passed the complete Research Skills pipeline, were merged to <code>main</code>, and were re-read from the authoritative branch.</p><table tabindex="0"><thead><tr><th>Column</th><th>Eligible Daily note</th><th>Validated judgment used in this synthesis</th></tr></thead><tbody><tr><td>Digital Employee</td><td>Computer Use Requires an Observable Action–State Loop</td><td>A model proposes actions; an external runtime executes, observes, governs, and verifies the resulting state.</td></tr><tr><td>Industry Architecture</td><td>A2A and MCP Define Different Interoperability Boundaries</td><td>Protocol choice should follow ownership of work, state, policy, and completion—not feature count alone.</td></tr><tr><td>Open-source Engineering</td><td>Manager Orchestration and Handoffs Encode Different Ownership Models</td><td>Specialist calls and handoffs are different operations because control and responsibility do not move in the same way.</td></tr></tbody></table><p>Academic Observations, older Weekly reports, and unvalidated source material were excluded from the evidence base. This report therefore synthesizes a small but coherent set of production-verified Daily observations rather than pretending to represent a broad market survey.</p><h2 id="executive-synthesis" tabindex="-1">Executive synthesis <a class="header-anchor" href="#executive-synthesis" aria-label="Permalink to &quot;Executive synthesis&quot;">​</a></h2><p>The three Daily notes examine different surfaces:</p><ul><li>GUI execution;</li><li>protocol interoperability;</li><li>multi-Agent orchestration.</li></ul><p>Their common architectural problem is the same:</p><blockquote><p><strong>Agentic systems fail when they move messages or actions without preserving who owns the work, who controls execution, who owns state, who grants authority, who may claim completion, and who independently verifies the outcome.</strong></p></blockquote><p>The new weekly conclusion is that <strong>ownership is the control plane of agentic work</strong>.</p><p>A reliable Digital Employee platform should not treat computer actions, MCP calls, manager-to-specialist calls, handoffs, and A2A delegation as interchangeable “tool use.” Each is a different work boundary with a different ownership transition.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Position + WorkOrder</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Work Boundary Control Plane</span></span>
<span class="line"><span>  ├─ Computer Operation boundary</span></span>
<span class="line"><span>  ├─ Capability boundary (MCP)</span></span>
<span class="line"><span>  ├─ Internal delegation boundary</span></span>
<span class="line"><span>  ├─ Handoff boundary</span></span>
<span class="line"><span>  └─ External Agent boundary (A2A)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Evidence Envelope</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Independent Completion Verifier</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Accepted outcome or governed recovery</span></span></code></pre></div><p><em>Diagram: joinwell52 Research Center synthesis from the three eligible Daily Research Notes.</em></p><h2 id="weekly-highlights" tabindex="-1">Weekly highlights <a class="header-anchor" href="#weekly-highlights" aria-label="Permalink to &quot;Weekly highlights&quot;">​</a></h2><ol><li><strong>Execution and completion are separate facts.</strong> A successful click, tool return, specialist response, or remote task state is not automatically a completed business outcome.</li><li><strong>Control transfer and work contribution are different.</strong> A manager may retain responsibility while a specialist contributes; a handoff may change the active owner; an external Agent may own a delegated task while the caller still owns acceptance.</li><li><strong>Protocol convergence does not remove semantic boundaries.</strong> MCP and A2A can both support long-running operations, but they still center different ownership relationships.</li><li><strong>Autonomy must be decomposed.</strong> Operational autonomy can increase while authority autonomy remains bounded by Position policy and human approval.</li><li><strong>Evidence must cross every boundary.</strong> The receiving side should not inherit a narrative claim of success; it should receive a structured evidence envelope sufficient for independent validation.</li></ol><h2 id="cross-analysis" tabindex="-1">Cross Analysis <a class="header-anchor" href="#cross-analysis" aria-label="Permalink to &quot;Cross Analysis&quot;">​</a></h2><h3 id="_1-computer-use-exposes-the-action–state-gap" tabindex="-1">1. Computer use exposes the action–state gap <a class="header-anchor" href="#_1-computer-use-exposes-the-action–state-gap" aria-label="Permalink to &quot;1. Computer use exposes the action–state gap&quot;">​</a></h3><p>The computer-use Daily note separates five facts:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proposed action</span></span>
<span class="line"><span>→ authorized action</span></span>
<span class="line"><span>→ executed action</span></span>
<span class="line"><span>→ resulting application state</span></span>
<span class="line"><span>→ completion judgment</span></span></code></pre></div><p>This shows why an Agent cannot be the sole authority over its own GUI work. The model can propose; the harness can execute; the target application owns the resulting business state; and a task-specific validator must decide whether the desired outcome actually holds.</p><p>The hidden ownership question is not “who clicked?” It is:</p><ul><li>who owns the WorkOrder;</li><li>who is permitted to act;</li><li>who records pre-state and post-state;</li><li>who can retry or compensate;</li><li>who may close the work.</li></ul><h3 id="_2-mcp-and-a2a-expose-the-service-boundary-gap" tabindex="-1">2. MCP and A2A expose the service-boundary gap <a class="header-anchor" href="#_2-mcp-and-a2a-expose-the-service-boundary-gap" aria-label="Permalink to &quot;2. MCP and A2A expose the service-boundary gap&quot;">​</a></h3><p>The protocol Daily note shows that feature lists are an unreliable basis for architecture. Both MCP and A2A can expose capabilities, long-running operations, progress, cancellation, and asynchronous behavior.</p><p>The durable distinction is accountability:</p><ul><li>MCP normally exposes a capability inside a Host-controlled workflow;</li><li>A2A normally delegates meaningful work to an independently operated Agent service.</li></ul><p>Therefore a protocol adapter must not silently decide the work model. The WorkOrder and Position contract should decide whether the operation is a capability invocation or an accountable delegation before transport is selected.</p><h3 id="_3-manager-and-handoff-expose-the-responsibility-transfer-gap" tabindex="-1">3. Manager and handoff expose the responsibility-transfer gap <a class="header-anchor" href="#_3-manager-and-handoff-expose-the-responsibility-transfer-gap" aria-label="Permalink to &quot;3. Manager and handoff expose the responsibility-transfer gap&quot;">​</a></h3><p>The orchestration Daily note shows that a manager calling a specialist retains conversational and completion ownership, while a handoff changes the active Agent and may transfer downstream responsibility.</p><p>This means that <code>from</code>, <code>to</code>, and a text message are insufficient runtime facts. The system must record the operation type:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>consult</span></span>
<span class="line"><span>assign_subtask</span></span>
<span class="line"><span>handoff</span></span>
<span class="line"><span>escalate</span></span>
<span class="line"><span>return</span></span></code></pre></div><p>Without that type, the runtime cannot reliably reconstruct who owns integration, who applies final guardrails, or who may declare completion.</p><h3 id="_4-unified-boundary-matrix" tabindex="-1">4. Unified boundary matrix <a class="header-anchor" href="#_4-unified-boundary-matrix" aria-label="Permalink to &quot;4. Unified boundary matrix&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Boundary</th><th>Work owner after boundary</th><th>Control owner</th><th>State owner</th><th>Completion claimant</th><th>Acceptance verifier</th></tr></thead><tbody><tr><td>Computer operation</td><td>Local WorkOrder owner usually remains accountable</td><td>Execution harness</td><td>Target application plus runtime evidence store</td><td>Local runtime or worker</td><td>Task-specific validator / human gate</td></tr><tr><td>MCP capability call</td><td>Host usually retains work ownership</td><td>Host orchestrates the server capability</td><td>Server capability state plus Host workflow state</td><td>Host workflow</td><td>Host-side business validator</td></tr><tr><td>Manager → specialist call</td><td>Manager retains parent work ownership</td><td>Manager</td><td>Manager run plus specialist subtask state</td><td>Specialist claims subtask result; manager claims parent completion</td><td>Manager, QA, or release gate</td></tr><tr><td>Handoff</td><td>Receiving Agent becomes active owner for the transferred scope</td><td>Receiving Agent within runtime policy</td><td>Shared run state with governed context transfer</td><td>Receiving Agent for the transferred scope</td><td>Defined downstream gate or returning owner</td></tr><tr><td>A2A delegated task</td><td>Remote Agent owns delegated task execution</td><td>Remote Agent service</td><td>Remote task lifecycle; caller retains local WorkOrder state</td><td>Remote Agent reports task state and artifacts</td><td>Caller-side acceptance validator</td></tr></tbody></table><p><em>Table: joinwell52 Research Center synthesis.</em></p><p>The matrix reveals a recurring rule: <strong>the party that reports progress is not necessarily the party authorized to accept completion</strong>.</p><h2 id="new-architecture-judgment-work-boundary-control-plane" tabindex="-1">New architecture judgment: Work Boundary Control Plane <a class="header-anchor" href="#new-architecture-judgment-work-boundary-control-plane" aria-label="Permalink to &quot;New architecture judgment: Work Boundary Control Plane&quot;">​</a></h2><p>The Research Center should add a <strong>Work Boundary Control Plane</strong> between Position-level work and every execution adapter.</p><p>This is not a second workflow engine. It is a semantic and evidence layer that preserves ownership across heterogeneous operations.</p><h3 id="required-objects" tabindex="-1">Required objects <a class="header-anchor" href="#required-objects" aria-label="Permalink to &quot;Required objects&quot;">​</a></h3><ol><li><strong>WorkBoundaryContract</strong> — defines the type and allowed ownership transition.</li><li><strong>OwnershipLedger</strong> — records durable before/after ownership facts.</li><li><strong>AuthorityDecision</strong> — records policy and human approval where required.</li><li><strong>ContextPackage</strong> — transfers only the context necessary for the receiving boundary.</li><li><strong>EvidenceEnvelope</strong> — returns structured observations, artifacts, state references, and execution facts.</li><li><strong>CompletionVerifier</strong> — independently decides whether the WorkOrder outcome is acceptable.</li></ol><h3 id="proposed-contract" tabindex="-1">Proposed contract <a class="header-anchor" href="#proposed-contract" aria-label="Permalink to &quot;Proposed contract&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">work_boundary_contract</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  boundary_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  work_order_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  boundary_type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">capability_call | subtask | handoff | external_delegation | computer_operation</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  from_actor_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  to_actor_or_adapter_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  work_scope</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  work_owner_before</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  work_owner_after</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  control_owner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  state_owner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  authority_source_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  context_package_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  expected_output_contract</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  evidence_envelope_contract</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  completion_claimant</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  completion_verifier</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  retry_owner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  compensation_owner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  return_or_escalation_condition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span></code></pre></div><h3 id="boundary-invariants" tabindex="-1">Boundary invariants <a class="header-anchor" href="#boundary-invariants" aria-label="Permalink to &quot;Boundary invariants&quot;">​</a></h3><ul><li>No boundary may change work ownership implicitly.</li><li>A completion claim must not automatically become an accepted outcome.</li><li>Context transfer must follow least privilege and exclude stale or untrusted material.</li><li>Retry and compensation ownership must be declared before consequential execution.</li><li>Protocol adapters may transport work but may not redefine Position authority or WorkOrder lifecycle semantics.</li><li>A resumed run must prove that it will not duplicate a consequential action.</li></ul><h2 id="contradictions-identified" tabindex="-1">Contradictions identified <a class="header-anchor" href="#contradictions-identified" aria-label="Permalink to &quot;Contradictions identified&quot;">​</a></h2><h3 id="autonomy-versus-authority" tabindex="-1">Autonomy versus authority <a class="header-anchor" href="#autonomy-versus-authority" aria-label="Permalink to &quot;Autonomy versus authority&quot;">​</a></h3><p>Computer use and remote delegation increase operational autonomy, but consequential organizational actions still require bounded authority. Treating more tool access as more authority is a category error.</p><p><strong>Resolution direction:</strong> represent operational capability and decision authority as separate fields in the Position and WorkBoundaryContract.</p><h3 id="protocol-convergence-versus-semantic-divergence" tabindex="-1">Protocol convergence versus semantic divergence <a class="header-anchor" href="#protocol-convergence-versus-semantic-divergence" aria-label="Permalink to &quot;Protocol convergence versus semantic divergence&quot;">​</a></h3><p>MCP Tasks and A2A Tasks may look increasingly similar at the transport level. Yet one normally serves Host-controlled capability integration while the other represents independent Agent collaboration.</p><p><strong>Resolution direction:</strong> select the work model first, then the protocol. Do not infer accountability from the presence of an asynchronous task handle.</p><h3 id="central-control-versus-orchestration-bottlenecks" tabindex="-1">Central control versus orchestration bottlenecks <a class="header-anchor" href="#central-control-versus-orchestration-bottlenecks" aria-label="Permalink to &quot;Central control versus orchestration bottlenecks&quot;">​</a></h3><p>The manager pattern provides consistent policy and integration, but a central manager can become slow, context-heavy, or distort specialist results. Handoffs reduce the central bottleneck but can fragment policy and completion ownership.</p><p><strong>Resolution direction:</strong> retain manager ownership for bounded, aggregative work; permit handoff only when the transferred scope, authority, return condition, and verifier are explicit.</p><h3 id="rich-context-versus-least-privilege" tabindex="-1">Rich context versus least privilege <a class="header-anchor" href="#rich-context-versus-least-privilege" aria-label="Permalink to &quot;Rich context versus least privilege&quot;">​</a></h3><p>Handoffs and remote collaboration benefit from context continuity, while safe execution requires minimizing sensitive, stale, or prompt-injected material.</p><p><strong>Resolution direction:</strong> use a governed ContextPackage rather than forwarding the complete transcript by default.</p><h3 id="self-reported-success-versus-independent-verification" tabindex="-1">Self-reported success versus independent verification <a class="header-anchor" href="#self-reported-success-versus-independent-verification" aria-label="Permalink to &quot;Self-reported success versus independent verification&quot;">​</a></h3><p>A remote Agent, specialist, or computer-use loop can report success. The caller still needs proof that the business state changed correctly and durably.</p><p><strong>Resolution direction:</strong> completion is a two-step protocol: <code>claim</code> followed by <code>accept</code> or <code>reject</code>.</p><h2 id="unresolved-questions" tabindex="-1">Unresolved questions <a class="header-anchor" href="#unresolved-questions" aria-label="Permalink to &quot;Unresolved questions&quot;">​</a></h2><ol><li>Which ownership dimensions belong in TMPA core objects, and which should remain runtime projections?</li><li>Can one EvidenceEnvelope cover GUI state, MCP tool results, specialist reports, and A2A artifacts without becoming too generic?</li><li>How should a parent WorkOrder behave when a handoff chain does not return to the original manager?</li><li>Which validators must be deterministic, and where is human judgment an accepted verification mechanism?</li><li>How should duplicate submission, timeout, cancellation, and compensation be represented across external Agent boundaries?</li><li>When a remote A2A Agent internally uses MCP tools, where should human approval be enforced and evidenced?</li><li>What evidence retention policy is sufficient for audit while minimizing privacy and storage risk?</li></ol><h2 id="engineering-judgment" tabindex="-1">Engineering judgment <a class="header-anchor" href="#engineering-judgment" aria-label="Permalink to &quot;Engineering judgment&quot;">​</a></h2><p>The next CodeFlowMu milestone should <strong>not</strong> begin by adding broad A2A, MCP, or unrestricted computer-use support.</p><p>The highest-leverage engineering sequence is:</p><h3 id="phase-0-—-semantic-foundation" tabindex="-1">Phase 0 — semantic foundation <a class="header-anchor" href="#phase-0-—-semantic-foundation" aria-label="Permalink to &quot;Phase 0 — semantic foundation&quot;">​</a></h3><ol><li>Add a typed delegation and boundary event model.</li><li>Add <code>work_owner</code>, <code>control_owner</code>, <code>completion_claimant</code>, and <code>completion_verifier</code> projections.</li><li>Define EvidenceEnvelope and CompletionVerifier interfaces.</li><li>Add explicit <code>waiting_human_authority</code>, <code>claim_submitted</code>, <code>verification_failed</code>, and <code>accepted</code> lifecycle states where applicable.</li></ol><h3 id="phase-1-—-controlled-adapters" tabindex="-1">Phase 1 — controlled adapters <a class="header-anchor" href="#phase-1-—-controlled-adapters" aria-label="Permalink to &quot;Phase 1 — controlled adapters&quot;">​</a></h3><ol><li>Wrap one local computer-operation case with pre-state, post-state, approval, and deterministic validation.</li><li>Wrap one bounded MCP capability call without transferring parent work ownership.</li><li>Implement one manager-to-specialist subtask and one explicit handoff using the same WorkBoundaryContract.</li><li>Simulate one A2A-style external delegation with a remote task state and local acceptance gate.</li></ol><h3 id="phase-2-—-comparative-experiment" tabindex="-1">Phase 2 — comparative experiment <a class="header-anchor" href="#phase-2-—-comparative-experiment" aria-label="Permalink to &quot;Phase 2 — comparative experiment&quot;">​</a></h3><p>Execute the same bounded business task through four paths:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>manager subtask</span></span>
<span class="line"><span>handoff</span></span>
<span class="line"><span>MCP capability</span></span>
<span class="line"><span>A2A delegation</span></span></code></pre></div><p>Compare:</p><ul><li>ownership clarity;</li><li>context transferred;</li><li>retry behavior;</li><li>evidence quality;</li><li>final-state verification;</li><li>recovery after interruption;</li><li>risk of duplicate consequential action.</li></ul><p>Only after these semantics are stable should CodeFlowMu add general protocol bridges or a full Digital Employee Studio.</p><h2 id="impact-on-the-research-center-architecture" tabindex="-1">Impact on the Research Center architecture <a class="header-anchor" href="#impact-on-the-research-center-architecture" aria-label="Permalink to &quot;Impact on the Research Center architecture&quot;">​</a></h2><h3 id="tmpa" tabindex="-1">TMPA <a class="header-anchor" href="#tmpa" aria-label="Permalink to &quot;TMPA&quot;">​</a></h3><p>This report does not modify TMPA publications. It supplies research input for separating:</p><ul><li>work assignment;</li><li>message transfer;</li><li>custody;</li><li>authority transfer;</li><li>execution control;</li><li>evidence custody;</li><li>completion claim;</li><li>completion acceptance.</li></ul><p>A deterministic reconstruction should preserve each transition rather than infer it from message order or file movement alone.</p><h3 id="digital-employee" tabindex="-1">Digital Employee <a class="header-anchor" href="#digital-employee" aria-label="Permalink to &quot;Digital Employee&quot;">​</a></h3><p>A Position definition should declare:</p><ul><li>work it may accept;</li><li>capabilities it may invoke;</li><li>work it may delegate;</li><li>authority it may exercise without approval;</li><li>applications and accounts it may operate;</li><li>context it may disclose;</li><li>completion it may claim;</li><li>outcomes it may finally approve.</li></ul><p>This turns the Digital Employee from a named Agent into an accountable organizational worker.</p><h3 id="codeflowmu" tabindex="-1">CodeFlowMu <a class="header-anchor" href="#codeflowmu" aria-label="Permalink to &quot;CodeFlowMu&quot;">​</a></h3><p>CodeFlowMu’s existing PM pattern should remain the default manager model: PM owns decomposition, integration, and parent completion. DEV, QA, and OPS contribute bounded work unless an explicit handoff changes ownership.</p><p>The runtime should expose:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>current work owner</span></span>
<span class="line"><span>active control owner</span></span>
<span class="line"><span>contributors</span></span>
<span class="line"><span>pending subtask owners</span></span>
<span class="line"><span>decision authority</span></span>
<span class="line"><span>release authority</span></span>
<span class="line"><span>completion claimant</span></span>
<span class="line"><span>completion verifier</span></span>
<span class="line"><span>last ownership transition</span></span></code></pre></div><p>FCoP lifecycle transitions remain useful custody evidence, but file movement alone should not be treated as the complete ownership model.</p><h2 id="queue-reprioritization" tabindex="-1">Queue reprioritization <a class="header-anchor" href="#queue-reprioritization" aria-label="Permalink to &quot;Queue reprioritization&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Queue item</th><th style="text-align:right;">Priority</th><th>Recommended transition</th><th>Reason</th></tr></thead><tbody><tr><td>WorkBoundaryContract and OwnershipLedger</td><td style="text-align:right;">P0</td><td>Candidate → Selected → Architecture Definition</td><td>It is the shared prerequisite for GUI, MCP, A2A, manager, and handoff execution.</td></tr><tr><td>CompletionVerifier and EvidenceEnvelope</td><td style="text-align:right;">P0</td><td>Candidate → Selected</td><td>Every eligible Daily note identifies a completion or evidence gap.</td></tr><tr><td>Human authority lifecycle node</td><td style="text-align:right;">P0</td><td>Candidate → Selected</td><td>Consequential actions need durable approval and resume semantics.</td></tr><tr><td>Comparative boundary experiment</td><td style="text-align:right;">P1</td><td>Candidate → Queue</td><td>Validates the architecture using one task across four work models.</td></tr><tr><td>A2A–FCoP external bridge</td><td style="text-align:right;">P2</td><td>Queue → Hold</td><td>Mapping should wait until ownership and acceptance semantics are stable.</td></tr><tr><td>General MCP skills/tasks integration</td><td style="text-align:right;">P2</td><td>Queue → Hold</td><td>Capability transport should not precede the Host-side work contract.</td></tr><tr><td>Unrestricted computer-use runtime</td><td style="text-align:right;">P2</td><td>Queue → Hold</td><td>Start with a controlled local application and executable validator.</td></tr><tr><td>Full Digital Employee Studio</td><td style="text-align:right;">P3</td><td>Backlog remains Backlog</td><td>Registry and UI expansion should follow runtime semantic proof.</td></tr></tbody></table><h2 id="lifecycle-transitions" tabindex="-1">Lifecycle transitions <a class="header-anchor" href="#lifecycle-transitions" aria-label="Permalink to &quot;Lifecycle transitions&quot;">​</a></h2><p>The three source Daily notes transition from <code>published</code> to <code>synthesized</code>, with Weekly 003 recorded as the synthesis consumer.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Daily 003 source objects</span></span>
<span class="line"><span>published</span></span>
<span class="line"><span>→ synthesis_selected</span></span>
<span class="line"><span>→ cross_analyzed</span></span>
<span class="line"><span>→ synthesized_in: weekly-003</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Weekly 003</span></span>
<span class="line"><span>candidate</span></span>
<span class="line"><span>→ selected</span></span>
<span class="line"><span>→ cross_analysis_complete</span></span>
<span class="line"><span>→ architecture_judgment_complete</span></span>
<span class="line"><span>→ engineering_judgment_complete</span></span>
<span class="line"><span>→ publication_editing_complete</span></span>
<span class="line"><span>→ published</span></span>
<span class="line"><span>→ commit_verified</span></span></code></pre></div><p>These transitions do not reopen or revise the original Daily publications. They record that the Daily evidence has been consumed by a higher synthesis layer.</p><h2 id="next-week-research" tabindex="-1">Next week research <a class="header-anchor" href="#next-week-research" aria-label="Permalink to &quot;Next week research&quot;">​</a></h2><ol><li>Draft WorkBoundaryContract V0.1 as a research schema, not yet a frozen TMPA object.</li><li>Define a minimal EvidenceEnvelope with concrete variants for GUI, capability call, specialist result, and remote Agent artifact.</li><li>Design the four-path comparative experiment and one deterministic final-state validator.</li><li>Specify human approval, timeout, cancellation, retry, and compensation transitions.</li><li>Test whether current FCoP custody events can project the proposed OwnershipLedger without protocol changes.</li></ol><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The week’s three validated Daily observations converge on a single engineering principle:</p><blockquote><p><strong>The core of Agent governance is not routing intelligence. It is preserving accountable ownership across every boundary where work, control, state, authority, evidence, or completion may move.</strong></p></blockquote><p>The practical consequence is clear: CodeFlowMu should establish the Work Boundary Control Plane before expanding protocol coverage or computer-operation autonomy.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li><a href="./../../digital-employee/2026-08-02-computer-use-action-state-loop">Digital Employee Daily 003 — Computer Use Requires an Observable Action–State Loop</a></li><li><a href="./../../industry/2026-08-02-a2a-mcp-interoperability-boundaries">Industry Architecture Daily 003 — A2A and MCP Define Different Interoperability Boundaries</a></li><li><a href="./../../engineering/2026-08-02-manager-handoff-ownership-models">Open-source Engineering Daily 003 — Manager Orchestration and Handoffs Encode Different Ownership Models</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/production-tests/production-test-v1/REPORT.md" target="_blank" rel="noreferrer">Research OS Engine Production Test V1 — evidence validation record</a></li></ol>`,105))])}const k=t(l,[["render",c]]);export{y as __pageData,k as default};
